import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();cams=['front','side'];o=r.get_obs(cameras=cams,include_depth=True);base=np.array(o.meta['proprio']['now'][58:87]);
# fixed table depth planes, fitted robustly to white tabletop pixels
planes={}
for c in cams:
 im=o.last[c];d=o.depth[c][0].astype(float);gray=im.mean(2);sat=im.max(2)-im.min(2);Y,X=np.mgrid[:240,:320]
 if c=='front':reg=(X>100)&(X<220)&(Y>115)&(Y<165)
 else:reg=(X>95)&(X<190)&(Y>105)&(Y<160)
 reg &= (gray>225)&(sat<35)&(d<3);A=np.stack([X[reg],Y[reg],np.ones(reg.sum())],1);b=d[reg];co=np.linalg.lstsq(A,b,rcond=None)[0]
 for _ in range(5):
  rr=b-A@co;keep=np.abs(rr-np.median(rr))<.006;A=A[keep];b=b[keep];co=np.linalg.lstsq(A,b,rcond=None)[0]
 planes[c]=co;print(c,'table plane',co,'pixels',len(b))
def feat(o):
 f=[]
 for c in cams:
  im=o.last[c];d=o.depth[c][0].astype(float);gray=im.mean(2);sat=im.max(2)-im.min(2);Y,X=np.mgrid[:240,:320];pred=planes[c][0]*X+planes[c][1]*Y+planes[c][2]
  if c=='front':roi=(X>140)&(X<195)&(Y>68)&(Y<135)
  else:roi=(X>118)&(X<215)&(Y>68)&(Y<137)
  m=roi&(gray>160)&(sat<60)&(d<pred-.015)&(d>.5);y,x=np.where(m)
  if len(x)<80:raise ValueError((c,'too few hand points',len(x)))
  # bottom 20% in image are the pointing fingers
  lo=np.quantile(y,.80);sel=y>=lo
  f.extend([x[sel].mean(),y[sel].mean()]);print(c,'tip pixels',len(x), 'tip center',x[sel].mean(),y[sel].mean())
 return np.array(f)
f0=feat(o);J=np.zeros((4,7));eps=.04
for j in range(7):
 a=base.copy();a[j]+=eps
 op=r.submit('joint_position',a,dt=.8,cameras=cams,video='frames',include_depth=True)
 op=r.get_obs(cameras=cams,seconds=.4,include_depth=True,video='frames');fp=feat(op)
 r.submit('joint_position',base,dt=.8,cameras=cams,video='frames',include_depth=True)
 ob=r.get_obs(cameras=cams,seconds=.4,include_depth=True,video='frames');fb=feat(ob)
 J[:,j]=(fp-fb)/eps;print('j',j,'diff',fp-fb,'J',J[:,j])
print('baseline tips',f0,'J\n',J,'sv',np.linalg.svd(J)[1])
np.savez('/app/output/jac_tips.npz',J=J,f0=f0,base=base,planes=planes)
